import {drawSprite,sortByDepth} from './vendor/pixel-agents/index.js';
import {worldToScreen} from './engine.js';
export const COLORS={done:'#b6d184',blocked:'#e2bd70',review:'#de9471',paused:'#bc9aa8',planned:'#a4b593',unknown:'#a2c4d3'};
const PALETTE={'.':'',o:'#283a35',h:'#ba934e',H:'#e7c773',s:'#e8c29a',d:'#b77f64',c:'#ae693e',C:'#e9b16e',b:'#36554b',B:'#263d3c',a:'#dfb66c',w:'#f2e6b9'};
const FRONT=['................','......oooo......','.....ohHHho.....','....ohHHHHho....','...ooHHHHHHoo...','...ohhhhhhhho...','....ossdsso.....','....osossoso....','.....osssso.....','......oddo......','....oCcwwcCo....','...oCccwwccCo...','...oscCccCcso...','...osbCccCbso...','....obCaaCbo....','.....obbbbo.....','.....obBBbo.....','.....oB..Bo.....','....ooB..Boo....','....ooo..ooo....'];
const BACK=['................','......oooo......','.....ohHHho.....','....ohHHHHho....','...ooHHHHHHoo...','...ohhhhhhhho...','....ohhhhho.....','....ohhhhho.....','.....ohhho......','......oddo......','....oCCccCCo....','...oCcoooocCo...','...osbwaaabso...','...osbwaawbso...','....obwaaabo....','.....obbbbo.....','.....obBBbo.....','.....oB..Bo.....','....ooB..Boo....','....ooo..ooo....'];
const SIDE=['................','......oooo......','.....ohHHho.....','....ohHHHHho....','....oHHHHHHoo...','....ohhhhhhho...','.....ohsssso....','.....ohsosso....','.....ohsssso....','......oddo......','.....oCwcco.....','.....oCwccCo....','.....oscccco....','.....osCccco....','.....obaacco....','.....obbbbo.....','.....oBBBbo.....','.....oB.Bo......','....ooB.Boo.....','....ooo.ooo.....'];
const spriteCache=new Map();
export function actorSprite(facing='down',frame=0,bot=false,tint='#a7c88e'){let key=[facing,frame,bot,tint].join('/');if(spriteCache.has(key))return spriteCache.get(key);let rows=facing==='up'?BACK:(facing==='left'||facing==='right')?SIDE:FRONT;let s=rows.map((r,ri)=>[...r].map((c,ci)=>{if(ri>16&&frame===1&&ci<8)return ri===19?'':PALETTE[c];if(ri>16&&frame===3&&ci>=8)return ri===19?'':PALETTE[c];let col=PALETTE[c];if(bot){if(['h','H'].includes(c))col=tint;if(['s','d'].includes(c))col='#adc8bd';if(c==='C')col='#d0daba';if(c==='c')col='#638876';}return col;}));if(facing==='left')s=s.map(r=>r.reverse());spriteCache.set(key,s);return s;}
export function drawActor(ctx,p,bot=false,tint){ctx.fillStyle='#132d3460';ctx.beginPath();ctx.ellipse(p.x,p.y+1,16,6,0,0,Math.PI*2);ctx.fill();drawSprite(ctx,actorSprite(p.facing||'down',p.frame||0,bot,tint),Math.round(p.x-16),Math.round(p.y-39),2);if(bot){ctx.fillStyle='#e5d18b';ctx.fillRect(p.x-2,p.y-48,4,5);ctx.fillStyle='#cddbb9';ctx.fillRect(p.x-1,p.y-44,2,5);}}
function rect(ctx,x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
function line(ctx,points,c,width=2,dash=[]){ctx.beginPath();ctx.strokeStyle=c;ctx.lineWidth=width;ctx.setLineDash(dash);points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();ctx.setLineDash([]);}
function txt(ctx,text,x,y,size=12,color='#f6efd4',align='center'){ctx.font=`${size}px sans-serif`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillStyle=color;ctx.fillText(text,x,y);}
function plaque(ctx,text,x,y,sub='',color='#d6c895',number=''){ctx.font='12px sans-serif';let width=Math.max(90,ctx.measureText(text).width+28+(number?28:0));let height=sub?45:27;rect(ctx,x-width/2+3,y+4,width,height,'#0a242761');rect(ctx,x-width/2,y,width,height,'#183c39ee');rect(ctx,x-width/2,y,width,2,color);let tx=x;if(number){rect(ctx,x-width/2+7,y+7,24,22,color);txt(ctx,number,x-width/2+19,y+18,11,'#263b31');tx+=12;}txt(ctx,text,tx,y+16,12);if(sub)txt(ctx,sub,x,y+33,9,'#b7cbb6');}
function plant(ctx,x,y,t){rect(ctx,x-12,y-7,25,20,'#5c4534');rect(ctx,x-14,y-8,29,6,t.trim);rect(ctx,x-3,y-43,6,39,'#46614a');[[x-16,y-28],[x+3,y-38],[x-22,y-47],[x+8,y-55]].forEach(([a,b])=>{rect(ctx,a,b,19,15,'#48755c');rect(ctx,a+3,b,13,7,'#73905c');});}
function cabinet(ctx,x,y,t,kind='books'){rect(ctx,x+6,y+7,150,105,'#172b2840');rect(ctx,x,y,150,102,'#604c3c');rect(ctx,x+4,y+4,142,94,t.trim);rect(ctx,x+9,y+9,132,85,'#263b37');for(let r=0;r<2;r++){for(let i=0;i<9;i++){let c=kind==='rack'?['#80989a','#415c55','#aac199'][i%3]:['#b68868','#8fa67f','#b8b182','#71989c','#b99aa1'][i%5];rect(ctx,x+14+i*13,y+16+r*41,9,29-(i%3)*3,c);rect(ctx,x+14+i*13,y+21+r*41,9,2,t.trim);}rect(ctx,x+5,y+47+r*43,140,5,'#9d7f52');}}
function windowFrame(ctx,x,y,t){rect(ctx,x,y,178,99,t.trim);rect(ctx,x+6,y+6,166,87,'#92c5ca');rect(ctx,x+6,y+53,166,40,'#9ab39d');rect(ctx,x+27,y+51,18,40,'#6e997e');rect(ctx,x+93,y+43,24,50,'#6c997b');rect(ctx,x+6,y+73,166,20,'#c5d0ad');rect(ctx,x+84,y+2,8,96,t.trim);rect(ctx,x+4,y+44,170,7,t.trim);rect(ctx,x-6,y+98,190,8,'#745c41');}
function floor(ctx,s){const t=s.theme;rect(ctx,0,0,s.width,s.height,'#142927');rect(ctx,70,65,s.width-140,s.height-130,t.wall);rect(ctx,94,188,s.width-188,s.height-282,t.floor);for(let y=188,r=0;y<s.height-94;y+=24,r++){rect(ctx,94,y,s.width-188,2,'#654f3540');for(let x=94+(r%2)*80;x<s.width-94;x+=160){rect(ctx,x,y,2,24,'#654f3555');rect(ctx,x+5,y+5,62,1,'#e6d09925');}}rect(ctx,80,170,s.width-160,23,t.trim);rect(ctx,80,174,s.width-160,6,'#8c704c');rect(ctx,80,s.height-100,s.width-160,20,t.wall);rect(ctx,80,s.height-102,s.width-160,4,t.trim);rect(ctx,80,176,19,s.height-257,t.trim);rect(ctx,s.width-100,176,19,s.height-257,t.trim);let cx=s.width/2;rect(ctx,cx-45,s.height-105,90,35,t.floor);rect(ctx,cx-43,s.height-102,86,4,'#d4bd85');for(let x=cx-39;x<cx+42;x+=13)rect(ctx,x,s.height-94,9,22,'#c6b890');windowFrame(ctx,cx-90,76,t);cabinet(ctx,125,76,t,s.world?.id==='harbor'?'rack':'books');cabinet(ctx,s.width-282,76,t);plant(ctx,135,228,t);plant(ctx,s.width-135,228,t);plant(ctx,135,s.height-132,t);plant(ctx,s.width-135,s.height-132,t);rect(ctx,cx-145,338,290,260,t.accent+'60');rect(ctx,cx-139,344,278,248,'#314f4c50');for(let x=cx-135;x<cx+139;x+=11){rect(ctx,x,346,5,3,t.trim+'90');rect(ctx,x,586,5,3,t.trim+'90');}}
function drawProp(ctx,e,t){let x=e.x,y=e.y-30;ctx.fillStyle='#122e2c50';ctx.beginPath();ctx.ellipse(x,y+25,68,17,0,0,Math.PI*2);ctx.fill();if(e.prop==='board'){rect(ctx,x-69,y-59,6,89,'#6a5138');rect(ctx,x+63,y-59,6,89,'#6a5138');rect(ctx,x-76,y-82,152,70,t.trim);rect(ctx,x-69,y-75,138,55,'#254c42');for(let i=0;i<3;i++){rect(ctx,x-55,y-65+i*15,6,6,i===0?'#b8d588':'#d4c894');rect(ctx,x-39,y-65+i*15,69-i*13,4,'#b7cbb28c');}}else if(e.prop==='gate'){rect(ctx,x-69,y-61,138,63,'#726850');rect(ctx,x-65,y-55,130,49,'#2c4340');for(let i=0;i<5;i++){rect(ctx,x-58+i*26,y-51,5,43,'#d4bc76');}rect(ctx,x-13,y-38,26,28,'#dfc17d');rect(ctx,x-8,y-46,16,13,'#aa9057');rect(ctx,x-3,y-28,6,10,'#6e643f');rect(ctx,x-72,y+4,144,9,t.trim);}else{rect(ctx,x-65,y-5,9,35,'#725a3f');rect(ctx,x+56,y-5,9,35,'#725a3f');rect(ctx,x-77,y-38,154,45,'#735436');rect(ctx,x-77,y-45,154,39,'#c19b63');rect(ctx,x-72,y-41,144,28,'#d4b579');if(e.prop==='chart'){rect(ctx,x-53,y-38,91,22,'#e3d9a7');line(ctx,[[x-44,y-24],[x-29,y-32],[x-13,y-22],[x+19,y-31]],'#7d9b75',3);rect(ctx,x+49,y-36,12,18,'#355e53');}else{rect(ctx,x-30,y-78,59,42,'#4b5a47');rect(ctx,x-25,y-73,49,31,'#a7cdb1');rect(ctx,x-4,y-36,9,9,'#2c4940');rect(ctx,x-17,y-28,36,5,'#5c6c52');rect(ctx,x-57,y-30,21,11,'#8a7770');rect(ctx,x+45,y-45,14,24,'#d8c79b');}}}
function drawEntity(ctx,e,s,nearest,time,visited){const t=s.theme,c=COLORS[e.state]||t.accent,isNear=e.id===nearest?.id;
if(e.type==='portal'||e.type==='stage'){ctx.fillStyle=isNear?'#e7dfa34d':'#132d3952';ctx.beginPath();ctx.ellipse(e.x,e.y+8,42,16,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle=isNear?'#f6e9a6':c;ctx.lineWidth=isNear?3:2;ctx.setLineDash([4,5]);ctx.beginPath();ctx.ellipse(e.x,e.y+8,36,12,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);if(e.type==='stage'){rect(ctx,e.x-20,e.y-24,40,22,'#3f5140');rect(ctx,e.x-23,e.y-26,46,5,t.trim);rect(ctx,e.x-13,e.y-22,26,18,c);txt(ctx,e.number,e.x,e.y-13,12,'#294337');}else{rect(ctx,e.x-3,e.y-29,6,35,'#815f3b');rect(ctx,e.x-17,e.y-34,35,22,c);txt(ctx,e.number,e.x,e.y-23,12,'#2c4234');}plaque(ctx,e.label,e.x,e.y-98,e.subtitle,c,e.number);if(visited.has(e.nodeId||e.worldId)){txt(ctx,'已到访',e.x,e.y+33,8,'#e3e4b9');}}
else if(e.type==='npc'||e.type==='guide'){drawActor(ctx,{...e,facing:'down',frame:0},true,t.accent);plaque(ctx,e.label,e.x,e.y-94,s.world?.npc?.execution||'固定档案向导',t.accent);if(isNear){txt(ctx,'•••',e.x,e.y-65,13,'#eedb91');}}
else if(e.type==='topic'||e.type==='evidence'){ctx.strokeStyle=isNear?'#f3e4a2':'#d9ce9a99';ctx.lineWidth=2;ctx.setLineDash([3,5]);ctx.beginPath();ctx.ellipse(e.x,e.y+5,23,9,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);rect(ctx,e.x-2,e.y-7,4,4,'#f1dda0');plaque(ctx,e.label,e.x,e.y-78,isNear?e.subtitle:'',t.accent);}
else if(e.type==='exit'){line(ctx,[[e.x-14,e.y-6],[e.x,e.y+8],[e.x+14,e.y-6]],'#e5d499',4);txt(ctx,e.label,e.x,e.y+26,10,'#f2e6be');}}
function drawRoads(ctx,s){if(s.level!=='region')return;for(let edge of s.world.edges){const a=s.entities.find(e=>e.nodeId===edge.from),b=s.entities.find(e=>e.nodeId===edge.to);if(!a||!b)continue;let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);if(d<1)continue;let ax=a.x+dx/d*50,ay=a.y+dy/d*50,bx=b.x-dx/d*50,by=b.y-dy/d*50;line(ctx,[[ax,ay],[bx,by]],'#173d3766',7);line(ctx,[[ax,ay],[bx,by]],edge.kind==='done'?'#d4df9c':'#dcc080',3,edge.kind==='done'?[]:[8,8]);let mx=(ax+bx)/2,my=(ay+by)/2;ctx.font='9px sans-serif';let wd=ctx.measureText(edge.label).width+16;rect(ctx,mx-wd/2,my-9,wd,18,'#26493bed');txt(ctx,edge.label,mx,my,9,'#e9e3bf');let angle=Math.atan2(dy,dx);line(ctx,[[bx-Math.cos(angle-.6)*12,by-Math.sin(angle-.6)*12],[bx,by],[bx-Math.cos(angle+.6)*12,by-Math.sin(angle+.6)*12]],'#e4d198',3);}}
export function renderScene(ctx,{scene:s,player,camera,images={},nearest=null,time=0,visited=new Set(),target=null}){let {width:W,height:H}=camera;ctx.imageSmoothingEnabled=false;rect(ctx,0,0,W,H,s.level==='world'?'#126385':'#102b2b');ctx.save();ctx.scale(camera.zoom,camera.zoom);ctx.translate(-camera.x,-camera.y);if(s.level==='world'){for(let y=Math.floor(camera.y/55)*55;y<camera.y+H/camera.zoom;y+=55)for(let x=Math.floor(camera.x/85)*85;x<camera.x+W/camera.zoom;x+=85){rect(ctx,x+Math.sin(y)*9,y,20,2,'#4597a338');rect(ctx,x+32,y+15,13,2,'#7bcbc428');}}let img=s.background&&images[s.background];if(img)ctx.drawImage(img,0,0,s.width,s.height);else{rect(ctx,0,0,s.width,s.height,'#17302f');txt(ctx,'正在展开场景…',player.x,player.y-85,13,'#d7d9bb');}if(s.level==='region'&&!s.background){txt(ctx,s.world.subject,s.width/2,229,18,'#eee1b1');}drawRoads(ctx,s);
if(target){ctx.strokeStyle='#f2db98bb';ctx.lineWidth=2;ctx.setLineDash([3,11]);ctx.beginPath();ctx.moveTo(player.x,player.y);ctx.lineTo(target.x,target.y);ctx.stroke();ctx.setLineDash([]);}
const draws=s.entities.map(e=>({y:e.y,draw:()=>drawEntity(ctx,e,s,nearest,time,visited)}));for(let e of sortByDepth(draws))e.draw();ctx.strokeStyle='#fbebacd9';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(player.x,player.y+2,20,8,0,0,Math.PI*2);ctx.stroke();drawActor(ctx,player);txt(ctx,'你',player.x,player.y-48,9,'#fff6d5');ctx.restore();let gradient=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.2,W/2,H/2,Math.max(W,H)*.67);gradient.addColorStop(0,'#09262500');gradient.addColorStop(1,'#071e294b');ctx.fillStyle=gradient;ctx.fillRect(0,0,W,H);if(target){const q=worldToScreen(target,camera);if(q.x<30||q.x>W-30||q.y<30||q.y>H-30){const a=Math.atan2(q.y-H/2,q.x-W/2),r=Math.min(W,H)*.35,tx=W/2+Math.cos(a)*r,ty=H/2+Math.sin(a)*r;ctx.save();ctx.translate(tx,ty);ctx.rotate(a);ctx.beginPath();ctx.fillStyle='#f0d799';ctx.moveTo(13,0);ctx.lineTo(-7,-8);ctx.lineTo(-7,8);ctx.closePath();ctx.fill();ctx.restore();txt(ctx,Math.round(Math.hypot(target.x-player.x,target.y-player.y)/32)+' 格',tx,ty+21,9,'#f5e2a8');}}}
export function renderMinimap(ctx,s,player,images,visited,target){const W=ctx.canvas.width,H=ctx.canvas.height;ctx.clearRect(0,0,W,H);rect(ctx,0,0,W,H,'#123c3d');const scale=Math.min(W/s.width,H/s.height),ox=(W-s.width*scale)/2,oy=(H-s.height*scale)/2;ctx.save();ctx.translate(ox,oy);ctx.scale(scale,scale);let img=s.background&&images[s.background];if(img){ctx.globalAlpha=.6;ctx.drawImage(img,0,0,s.width,s.height);ctx.globalAlpha=1;}else{rect(ctx,80,170,s.width-160,s.height-270,s.theme.floor);s.obstacles.forEach(o=>rect(ctx,o.x,o.y,o.w,o.h,'#445d48'));}s.entities.filter(e=>['portal','stage','exit','topic'].includes(e.type)).forEach(e=>{rect(ctx,e.x-17,e.y-17,34,34,COLORS[e.state]||'#d0cf99');});if(target){ctx.strokeStyle='#fff4bb';ctx.lineWidth=10;ctx.strokeRect(target.x-29,target.y-29,58,58);}ctx.fillStyle='#fffde5';ctx.beginPath();ctx.arc(player.x,player.y,24,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#314944';ctx.lineWidth=8;ctx.stroke();ctx.restore();}
